'use strict';

// MODULES //

var parseURL = require( 'url' ).parse;
var objectKeys = require( '@stdlib/utils/keys' );
var format = require( '@stdlib/string/format' );
var defaults = require( './defaults.json' );
var targets = require( './targets.js' );


// VARIABLES //

var OPTION_KEYS = {
	'excludeSectionRoles': true,
	'includeProvenance': true,
	'mode': true,
	'moduleMap': true,
	'target': true,
	'unsupportedCode': true
};


// FUNCTIONS //

/**
* Tests whether a value is a non-array object.
*
* @private
* @param {*} value - value
* @returns {boolean} boolean
*/
function isObject( value ) {
	return value !== null && typeof value === 'object' && !Array.isArray( value );
}

/**
* Tests whether a URL contains a forbidden character.
*
* @private
* @param {string} value - URL
* @returns {boolean} boolean
*/
function hasUnsafeURLChar( value ) {
	var code;
	var ch;
	var i;

	for ( i = 0; i < value.length; i++ ) {
		ch = value.charAt( i );
		code = value.charCodeAt( i );
		if ( code <= 32 || code === 127 || ch === '\\' || /\s/.test( ch ) ) {
			return true;
		}
	}
	return false;
}

/**
* Tests whether a URL is allowed by the v1 module-map policy.
*
* @private
* @param {string} value - URL
* @returns {boolean} boolean
*/
function isURL( value ) {
	var parsed;

	if (
		typeof value !== 'string' ||
		value.length === 0 ||
		hasUnsafeURLChar( value )
	) {
		return false;
	}
	if ( /^\/(?!\/)/.test( value ) ) {
		return true;
	}
	if ( value.slice( 0, 8 ) !== 'https://' ) {
		return false;
	}
	try {
		parsed = parseURL( value );
	} catch ( err ) { // eslint-disable-line no-unused-vars
		return false;
	}
	return (
		parsed.protocol === 'https:' &&
		parsed.slashes === true &&
		typeof parsed.hostname === 'string' &&
		parsed.hostname.length > 0 &&
		parsed.auth === null
	);
}

/**
* Tests whether a module-map specifier excludes control characters and slashes.
*
* @private
* @param {string} value - specifier
* @returns {boolean} boolean
*/
function isSpecifier( value ) {
	var code;
	var i;

	if ( value.length === 0 ) {
		return false;
	}
	for ( i = 0; i < value.length; i++ ) {
		code = value.charCodeAt( i );
		if ( code < 32 || value.charAt( i ) === '\\' ) {
			return false;
		}
	}
	return true;
}

/**
* Copies and validates a module-map record.
*
* @private
* @param {string} specifier - module specifier
* @param {Object} record - module-map record
* @throws {TypeError} record is invalid
* @returns {Object} copied record
*/
function moduleRecord( specifier, record ) {
	var allowed = {
		'export': true,
		'mutable': true,
		'runtimes': true,
		'url': true
	};
	var value;
	var seen = Object.create( null );
	var keys;
	var out;
	var i;

	if ( !isObject( record ) ) {
		throw new TypeError( 'invalid option. `moduleMap` values must be objects.' );
	}
	keys = objectKeys( record );
	for ( i = 0; i < keys.length; i++ ) {
		if ( !allowed[ keys[ i ] ] ) {
			throw new TypeError( format( 'invalid option. Unrecognized `moduleMap` record field: `%s`.', keys[ i ] ) );
		}
	}
	if ( record.export !== 'default' && record.export !== 'namespace' ) {
		throw new TypeError( format( 'invalid option. `moduleMap[%s].export` must be either `default` or `namespace`.', specifier ) );
	}
	if ( typeof record.mutable !== 'boolean' ) {
		throw new TypeError( format( 'invalid option. `moduleMap[%s].mutable` must be a boolean.', specifier ) );
	}
	if ( !isURL( record.url ) ) {
		throw new TypeError( format( 'invalid option. `moduleMap[%s].url` must be an HTTPS or root-absolute same-origin URL.', specifier ) );
	}
	if ( !Array.isArray( record.runtimes ) || record.runtimes.length === 0 ) {
		throw new TypeError( format( 'invalid option. `moduleMap[%s].runtimes` must be a non-empty array.', specifier ) );
	}
	out = {
		'export': record.export,
		'mutable': record.mutable,
		'runtimes': [],
		'url': record.url
	};
	for ( i = 0; i < record.runtimes.length; i++ ) {
		value = record.runtimes[ i ];
		if ( ( value !== 'worker' && value !== 'iframe' ) || seen[ value ] ) {
			throw new TypeError( 'invalid option. `moduleMap` runtimes must be unique `worker` or `iframe` values.' );
		}
		seen[ value ] = true;
		out.runtimes.push( value );
	}
	return out;
}

/**
* Copies and validates a module map.
*
* @private
* @param {Object} value - module map
* @throws {TypeError} module map is invalid
* @returns {Object} copied module map
*/
function moduleMap( value ) {
	var keys;
	var out = Object.create( null );
	var key;
	var i;

	if ( !isObject( value ) ) {
		throw new TypeError( 'invalid option. `moduleMap` must be an object.' );
	}
	keys = objectKeys( value );
	for ( i = 0; i < keys.length; i++ ) {
		key = keys[ i ];
		if ( !isSpecifier( key ) ) {
			throw new TypeError( 'invalid option. `moduleMap` contains an invalid module specifier.' );
		}
		out[ key ] = moduleRecord( key, value[ key ] );
	}
	return out;
}

/**
* Copies and validates excluded semantic section roles.
*
* @private
* @param {Array} value - section roles
* @throws {TypeError} roles are invalid
* @returns {Array} copied section roles
*/
function sectionRoles( value ) {
	var seen = Object.create( null );
	var role;
	var out = [];
	var i;

	if ( !Array.isArray( value ) ) {
		throw new TypeError( 'invalid option. `excludeSectionRoles` must be an array.' );
	}
	for ( i = 0; i < value.length; i++ ) {
		role = value[ i ];
		if ( typeof role !== 'string' || role.length === 0 ) {
			throw new TypeError( 'invalid option. `excludeSectionRoles` must contain non-empty strings.' );
		}
		if ( seen[ role ] ) {
			throw new TypeError( 'invalid option. `excludeSectionRoles` must contain unique roles.' );
		}
		seen[ role ] = true;
		out.push( role );
	}
	return out;
}


// MAIN //

/**
* Validates and copies converter options.
*
* @param {Object} [options] - options
* @throws {TypeError} options are invalid
* @returns {Object} normalized options
*/
function validate( options ) {
	var keys;
	var out;
	var i;

	if ( arguments.length && !isObject( options ) ) {
		throw new TypeError( 'invalid argument. Options must be an object.' );
	}
	options = options || {};
	keys = objectKeys( options );
	for ( i = 0; i < keys.length; i++ ) {
		if ( !OPTION_KEYS[ keys[ i ] ] ) {
			throw new TypeError( format( 'invalid option. Unrecognized option: `%s`.', keys[ i ] ) );
		}
	}
	out = {
		'excludeSectionRoles': sectionRoles( ( options.excludeSectionRoles === void 0 ) ? defaults.excludeSectionRoles : options.excludeSectionRoles ),
		'includeProvenance': ( options.includeProvenance === void 0 ) ? defaults.includeProvenance : options.includeProvenance,
		'mode': ( options.mode === void 0 ) ? defaults.mode : options.mode,
		'moduleMap': ( options.moduleMap === void 0 ) ? Object.create( null ) : moduleMap( options.moduleMap ),
		'target': ( options.target === void 0 ) ? defaults.target : options.target,
		'unsupportedCode': options.unsupportedCode
	};
	if ( typeof out.includeProvenance !== 'boolean' ) {
		throw new TypeError( 'invalid option. `includeProvenance` must be a boolean.' );
	}
	if ( out.mode !== 'strict' && out.mode !== 'permissive' ) {
		throw new TypeError( 'invalid option. `mode` must be either `strict` or `permissive`.' );
	}
	if ( !targets[ out.target ] ) {
		throw new TypeError( 'invalid option. Unsupported JupyterLite `target`.' );
	}
	if ( out.unsupportedCode === void 0 ) {
		out.unsupportedCode = ( out.mode === 'strict' ) ? 'error' : 'markdown';
	}
	if ( out.unsupportedCode !== 'error' && out.unsupportedCode !== 'markdown' ) {
		throw new TypeError( 'invalid option. `unsupportedCode` must be either `error` or `markdown`.' );
	}
	return out;
}


// EXPORTS //

module.exports = validate;
